            if (ddr_axi3_axi_awvalid && ddr_axi3_axi_awready) begin
                ddr_axi3_aw_arb_locked <= 1'b0;
                ddr_axi3_aw_arb_rr <= (ddr_axi3_aw_arb_gnt == 1'd1) ? 1'd0 : ddr_axi3_aw_arb_gnt + 1'b1;
